* REPT1 -- Management dashboard with print dispatch
MAP REPT1 SIZE 24x80
  FIELD HEADER   AT 0,2   LEN 60 PROT BRIGHT COLOR=WHITE
  FIELD USERID   AT 0,70  LEN 8  PROT DIM    COLOR=TURQUOISE
  FIELD TOTCLI   AT 4,30  LEN 5  PROT BRIGHT COLOR=GREEN
  FIELD ACTORD   AT 5,30  LEN 5  PROT BRIGHT COLOR=YELLOW
  FIELD TOTVAL   AT 6,30  LEN 14 PROT BRIGHT COLOR=TURQUOISE
  FIELD ORD1ID   AT 10,10 LEN 10 PROT DIM    COLOR=WHITE
  FIELD ORD1CLI  AT 10,22 LEN 8  PROT DIM    COLOR=TURQUOISE
  FIELD ORD1TYPE AT 10,32 LEN 2  PROT DIM    COLOR=TURQUOISE
  FIELD ORD1VAL  AT 10,36 LEN 13 PROT DIM    COLOR=GREEN
  FIELD ORD1STAT AT 10,51 LEN 1  PROT DIM    COLOR=YELLOW
  FIELD MESSAGE  AT 15,5  LEN 60 PROT DIM    COLOR=YELLOW
  FIELD FOOTER   AT 23,2  LEN 70 PROT DIM    COLOR=BLUE
ENDMAP
